class Solution {
    public int[] rowAndMaximumOnes(int[][] mat){
        int bestRow=0,bestCount=0;
        for(int row=0;row<mat.length;row++){
            int count=0;
            for(int value:mat[row])count+=value;
            if(count>bestCount){
                bestCount=count;
                bestRow=row;
            }
        }
        return new int[]{
            bestRow,bestCount
        };
    }
}

code.kotlin:
class Solution {
    fun rowAndMaximumOnes(mat:Array<IntArray>):IntArray{
        var bestRow=0;
        var bestCount=0;
        for(row in mat.indices){
            val count=mat[row].sum();
            if(count>bestCount){
                bestCount=count;
                bestRow=row
            }
        };
        return intArrayOf(bestRow,bestCount)
    }
}

